    current_match = re.match(r"^S(\d{2})E(\d{2,3})$", str(current or ""))
    latest_match = re.match(r"^S(\d{2})E(\d{2,3})$", str(latest or ""))
    if not current_match or not latest_match:
        return ""
    current_season, current_episode = map(int, current_match.groups())
